1	// CLI entry: `contract-sentry audit <path>`.
2	// All public results are a single JSON object on stdout with stable order.
3	
4	import fs from 'node:fs';
5	import path from 'node:path';
6	import { parse, ParseError } from './parser.js';
7	import { LexError } from './lexer.js';
8	import { analyze } from './analyzer.js';
9	
10	const RULE_ORDER = [
11	  'DELEGATECALL_UNTRUSTED_TARGET',
12	  'UNCHECKED_EXTERNAL_CALL',
13	  'STATE_UPDATE_AFTER_CALL',
14	];
15	
16	function emit(obj) {
17	  process.stdout.write(`${JSON.stringify(obj, null, 2)}\n`);
18	}
19	
20	export class CliError extends Error {
21	  constructor(code, payload, exitCode) {
22	    super(code);
23	    this.code = code;
24	    this.payload = payload;
25	    this.exitCode = exitCode;
26	  }
27	}
28	
29	// Recursively collect .sol files. Returns POSIX-style relative display
30	// paths: relative to cwd for a single file argument, `<dir>/...` for a
31	// directory argument.
32	export function collectSolFiles(inputPath) {
33	  let stat;
34	  try {
35	    stat = fs.statSync(inputPath);
36	  } catch (e) {
37	    throw new CliError('INPUT_READ_ERROR', {
38	      error: 'INPUT_READ_ERROR',
39	      file: inputPath,
40	      message: e.message,
41	    }, 2);
42	  }
43	
44	  if (stat.isFile()) {
45	    if (!inputPath.endsWith('.sol')) return [];
46	    const abs = path.resolve(inputPath);
47	    const rel = path.relative(process.cwd(), abs).split(path.sep).join('/');
48	    return [{ abs, rel }];
49	  }
50	
51	  if (stat.isDirectory()) {
52	    const dirAbs = path.resolve(inputPath);
53	    const dirName = path.basename(dirAbs);
54	    const found = [];
55	    const walk = (dir) => {
56	      let entries;
57	      try {
58	        entries = fs.readdirSync(dir, { withFileTypes: true });
59	      } catch (e) {
60	        throw new CliError('INPUT_READ_ERROR', {
61	          error: 'INPUT_READ_ERROR',
62	          file: dir,
63	          message: e.message,
64	        }, 2);
65	      }
66	      for (const ent of entries) {
67	        const full = path.join(dir, ent.name);
68	        if (ent.isDirectory()) walk(full);
69	        else if (ent.isFile() && ent.name.endsWith('.sol')) {
70	          const inner = path.relative(dirAbs, full).split(path.sep).join('/');
71	          found.push({ abs: full, rel: `${dirName}/${inner}` });
