1	// Hand-written recursive-descent parser for the Solidity subset the
2	// analyzer needs. Tolerant by design: anything irrelevant to the three
3	// rules (events, structs, pragmas, imports, ...) is skipped structurally.
4	
5	import { lex } from './lexer.js';
6	
7	export class ParseError extends Error {
8	  constructor(message, token) {
9	    super(message);
10	    this.name = 'ParseError';
11	    this.startLine = token.startLine;
12	    this.startColumn = token.startColumn;
13	    this.startOffset = token.start;
14	  }
15	}
16	
17	const PUNCT = (t, v) => t.type === 'punct' && t.value === v;
18	const IS = (t, v) => t.type === 'punct' && t.value === v;
19	const KW = (t, v) => t.type === 'keyword' && t.value === v;
20	const TYPE_KEYWORDS = new Set(['address']);
21	const LOCATION_KEYWORDS = new Set(['memory', 'storage', 'calldata']);
22	const STATE_VAR_KEYWORDS = new Set([
23	  'public', 'private', 'internal', 'constant', 'immutable', 'override',
24	]);
25	
26	function spanOf(startTok, endTok) {
27	  return {
28	    startOffset: startTok.start,
29	    endOffset: endTok.end,
30	    startLine: startTok.startLine,
31	    startColumn: startTok.startColumn,
32	    endLine: endTok.endLine,
33	    endColumn: Math.max(1, endTok.endColumn - 1),
34	  };
35	}
36	
37	export function parse(source) {
38	  const tokens = lex(source.charCodeAt(0) === 0xfeff ? source.slice(1) : source);
39	  const p = new Parser(tokens);
40	  return p.parseSourceUnit();
41	}
42	
43	class Parser {
44	  constructor(tokens) {
45	    this.tokens = tokens;
46	    this.pos = 0;
47	  }
48	
49	  peek(k = 0) { return this.tokens[this.pos + k]; }
50	  cur() { return this.tokens[this.pos]; }
51	  atEnd() { return this.cur().type === 'eof'; }
52	  is(v) { return IS(this.cur(), v); }
53	  isKw(v) { return KW(this.cur(), v); }
54	  nextIs(v, k = 0) { const t = this.peek(k); return t && IS(t, v); }
55	  nextIsKw(v, k = 0) { const t = this.peek(k); return t && KW(t, v); }
56	
57	  eat(v) {
58	    if (!this.is(v)) {
59	      throw new ParseError(`Expected '${v}' but found '${this.cur().value || this.cur().type}'`, this.cur());
60	    }
61	    this.pos++;
62	  }
63	  eatKw(v) {
64	    if (!this.isKw(v)) {
65	      throw new ParseError(`Expected '${v}' but found '${this.cur().value || this.cur().type}'`, this.cur());
66	    }
67	    this.pos++;
68	  }
69	  accept(v) {
70	    if (this.is(v)) { this.pos++; return true; }
71	    return false;
72	  }
73	  acceptKw(v) {
74	    if (this.isKw(v)) { this.pos++; return true; }
75	    return false;
76	  }
77	  expectIdent() {
78	    const t = this.cur();
79	    if (t.type !== 'ident' && !(t.type === 'keyword' && TYPE_KEYWORDS.has(t.value))) {
80	      throw new ParseError(`Expected identifier but found '${t.value || t.type}'`, t);
81	    }
82	    this.pos++;
83	    return t.value;
84	  }
85	
86	  loc(startTok, endTok = this.tokens[this.pos - 1]) {
87	    return spanOf(startTok, endTok);
88	  }
89	
90	  // ---- Top level -------------------------------------------------------
91	
92	  parseSourceUnit() {
93	    const node = { kind: 'sourceUnit', contracts: [], freeFunctions: [], freeVariables: [] };
94	    while (!this.atEnd()) {
95	      const t = this.cur();
96	      if (this.isKw('pragma')) { this.skipToSemicolon(); continue; }
97	      if (this.isKw('import')) { this.skipImport(); continue; }
98	      if (this.isKw('abstract')) {
99	        const save = this.pos;
100	        this.pos++;
101	        if (this.isKw('contract')) {
102	          this.pos++;
103	          node.contracts.push(this.parseContract('abstract contract'));
104	        } else {
105	          this.pos = save;
106	          throw new ParseError(`Unexpected token 'abstract'`, t);
107	        }
108	        continue;
109	      }
110	      if (this.isKw('contract') || this.isKw('interface') || this.isKw('library')) {
111	        const kind = this.cur().value;
112	        this.pos++;
113	        node.contracts.push(this.parseContract(kind));
114	        continue;
115	      }
116	      if (this.isKw('using')) { this.skipToSemicolon(); continue; }
117	      if (this.isKw('type')) { this.skipToSemicolon(); continue; }
118	      if (this.isKw('function')) {
119	        node.freeFunctions.push(this.parseFunction(null, 'function'));
120	        continue;
121	      }
122	      // free constant variable / error / anything type-led
123	      if (this.isKw('error') || this.isKw('event') || this.isKw('struct') || this.isKw('enum')) {
124	        this.skipMemberDeclaration();
125	        continue;
126	      }
127	      // file-level constant variable e.g. `uint256 constant X = ...;`
128	      if (this.tryParseStateVariable(null)) continue;
129	      throw new ParseError(`Unexpected token '${t.value || t.type}' at top level`, t);
130	    }
131	    return node;
132	  }
133	
134	  skipToSemicolon() {
135	    let depth = 0;
136	    while (!this.atEnd()) {
137	      const t = this.cur();
138	      if (IS(t, '(') || IS(t, '[') || IS(t, '{')) depth++;
139	      else if (IS(t, ')') || IS(t, ']') || IS(t, '}')) depth--;
140	      else if (IS(t, ';') && depth === 0) { this.pos++; return; }
141	      this.pos++;
142	    }
143	  }
144	
145	  skipImport() {
146	    // import ... ;  (may contain braces)
147	    let depth = 0;
148	    while (!this.atEnd()) {
149	      const t = this.cur();
150	      if (IS(t, '{')) depth++;
151	      else if (IS(t, '}')) depth--;
152	      else if (IS(t, ';') && depth === 0) { this.pos++; return; }
153	      this.pos++;
154	    }
155	  }
156	
157	  parseContract(kind) {
158	    const startTok = this.tokens[this.pos - 1];
159	    const name = this.expectIdent();
160	    const bases = [];
161	    if (this.acceptKw('is')) {
162	      for (;;) {
163	        const path = [this.expectIdent()];
164	        while (this.accept('.')) path.push(this.expectIdent());
165	        // base constructor arguments
166	        if (this.is('(')) this.skipBalancedParens();
167	        bases.push(path[path.length - 1]);
168	        if (!this.accept(',')) break;
169	      }
170	    }
171	    this.eat('{');
172	    const contract = {
173	      kind, name, bases, nodes: [], stateVariables: [], loc: this.loc(startTok),
174	    };
175	    while (!this.is('}') && !this.atEnd()) {
176	      if (this.isKw('function')) { contract.nodes.push(this.parseFunction(name, 'function')); continue; }
177	      if (this.isKw('constructor')) { contract.nodes.push(this.parseFunction(name, 'constructor')); continue; }
178	      if (this.isKw('fallback')) { contract.nodes.push(this.parseFunction(name, 'fallback')); continue; }
179	      if (this.isKw('receive')) { contract.nodes.push(this.parseFunction(name, 'receive')); continue; }
180	      if (this.isKw('modifier')) { contract.nodes.push(this.parseFunction(name, 'modifier')); continue; }
181	      if (this.tryParseStateVariable(name, contract)) continue;
182	      this.skipMemberDeclaration();
183	    }
184	    this.eat('}');
185	    contract.loc = this.loc(startTok);
186	    return contract;
187	  }
188	
189	  skipBalancedParens() {
190	    this.eat('(');
191	    let depth = 1;
192	    while (!this.atEnd() && depth > 0) {
193	      const t = this.cur();
194	      if (IS(t, '(')) depth++;
195	      else if (IS(t, ')')) depth--;
196	      this.pos++;
197	    }
198	  }
199	
200	  skipMemberDeclaration() {
201	    // Skips event/error/struct/enum/using/type declarations to ';' or
202	    // balanced '{}'.
203	    const start = this.pos;
204	    if (this.isKw('using')) { this.skipToSemicolon(); return; }
205	    if (this.isKw('type')) { this.skipToSemicolon(); return; }
206	    if (this.isKw('error') || this.isKw('event')) { this.skipToSemicolon(); return; }
207	    if (this.isKw('struct') || this.isKw('enum') || this.isKw('contract') ||
208	        this.isKw('interface') || this.isKw('library')) {
209	      this.pos = start;
210	      // name then brace body
211	      this.pos++; // keyword
212	      if (this.cur().type === 'ident') this.pos++;
213	      while (!this.is('{') && !this.atEnd()) this.pos++;
214	      if (this.is('{')) {
215	        let depth = 0;
216	        do {
217	          const t = this.cur();
218	          if (IS(t, '{')) depth++;
219	          else if (IS(t, '}')) depth--;
220	          this.pos++;
221	        } while (!this.atEnd() && depth > 0);
222	      }
223	      this.accept(';');
224	      return;
225	    }
226	    // Unknown member: skip to ; or }, consuming balanced braces/parens.
227	    let depth = 0;
228	    while (!this.atEnd()) {
229	      const t = this.cur();
230	      if (IS(t, '(') || IS(t, '{') || IS(t, '[')) depth++;
231	      else if (IS(t, ')') || IS(t, '}') || IS(t, ']')) {
232	        if (depth === 0) return;
233	        depth--;
234	      } else if (IS(t, ';') && depth === 0) { this.pos++; return; }
235	      this.pos++;
236	    }
237	  }
238	
239	  // ---- State variables --------------------------------------------------
240	
241	  tryParseStateVariable(contractName, contract = null) {
242	    const save = this.pos;
243	    let typeNode;
244	    try {
245	      typeNode = this.parseTypeName();
246	    } catch (e) {
247	      this.pos = save;
248	      return false;
249	    }
250	    if (this.pos === save) { this.pos = save; return false; }
251	
252	    // modifiers can appear between type and name: `mapping(..) public x`
253	    while (this.cur().type === 'keyword' && STATE_VAR_KEYWORDS.has(this.cur().value)) {
254	      this.pos++;
255	      if (this.is('(')) this.skipBalancedParens(); // override(...)
256	    }
257	    if (this.cur().type !== 'ident') { this.pos = save; return false; }
258	    // Reject things that are clearly not declarations.
259	    const nameTok = this.cur();
260	    const after = this.peek(1);
261	    if (after && (IS(after, '('))) { this.pos = save; return false; }
262	
263	    const name = nameTok.value;
264	    this.pos++;
265	    let visibility = 'internal';
266	    // Visibility was consumed above; recover it:
267	    // (simpler: re-scan consumed tokens) -- track via keyword loop redo:
268	    // Instead inspect declaration by a lightweight rescan below.
269	    let initializer = null;
270	    if (this.accept('=')) initializer = this.parseExpression();
271	    const endTok = this.tokens[this.pos - 1];
272	    this.accept(';');
273	
274	    // Recover visibility / mutability by rescanning consumed tokens.
275	    visibility = 'internal';
276	    let isConstant = false;
277	    let isImmutable = false;
278	    for (let i = save + 1; i < this.pos; i++) {
279	      const tk = this.tokens[i];
280	      if (tk.type === 'keyword' && tk.value === 'public') visibility = 'public';
281	      if (tk.type === 'keyword' && tk.value === 'private') visibility = 'private';
282	      if (tk.type === 'keyword' && tk.value === 'external') visibility = 'external';
283	      if (tk.type === 'keyword' && tk.value === 'constant') isConstant = true;
284	      if (tk.type === 'keyword' && tk.value === 'immutable') isImmutable = true;
285	    }
286	
287	    const sv = {
288	      kind: 'stateVariable', name, visibility, isConstant, isImmutable,
289	      typeNode,
290	      contractName,
291	    };
292	    sv.loc = this.loc(this.tokens[save], endTok);
293	    if (contract) contract.stateVariables.push(sv);
294	    return true;
295	  }
296	
297	  // ---- Functions --------------------------------------------------------
298	
299	  parseFunction(contractName, kind) {
300	    const startTok = this.cur();
301	    this.pos++; // keyword
302	
303	    let name = null;
304	    if (kind === 'function' || kind === 'modifier') {
305	      if (this.cur().type === 'ident') {
306	        name = this.cur().value;
307	        this.pos++;
308	      } else if (kind === 'function') {
309	        // unnamed function: old-style fallback
310	        kind = 'fallback';
311	      }
312	    }
313	
314	    const params = (kind === 'modifier' && !this.is('(')) ? [] : this.parseParameterList();
315	    let returnParams = [];
316	    if (this.acceptKw('returns')) returnParams = this.parseParameterList();
317	
318	    let visibility = null;
319	    let stateMutability = null;
320	    let isVirtual = false;
321	    const modifiers = [];
322	    while (!this.is('{') && !this.is(';') && !this.atEnd()) {
323	      const t = this.cur();
324	      if (t.type === 'keyword') {
325	        if (t.value === 'public' || t.value === 'external' ||
326	            t.value === 'internal' || t.value === 'private') {
327	          visibility = t.value; this.pos++; continue;
328	        }
329	        if (t.value === 'pure' || t.value === 'view' || t.value === 'payable') {
330	          stateMutability = t.value; this.pos++; continue;
331	        }
332	        if (t.value === 'virtual') { isVirtual = true; this.pos++; continue; }
333	        if (t.value === 'constant') { this.pos++; continue; }
334	        if (t.value === 'override') {
335	          this.pos++;
336	          if (this.is('(')) this.skipBalancedParens();
337	          continue;
338	        }
339	        if (t.value === 'returns') {
340	          this.pos++;
341	          returnParams = this.parseParameterList();
342	          continue;
343	        }
344	      }
345	      // modifier invocation: path optionally followed by args
346	      const modName = this.parseModifierInvocation();
347	      modifiers.push(modName);
348	    }
349	    if (visibility === null) {
350	      if (kind === 'fallback' || kind === 'receive') visibility = 'external';
351	      else visibility = 'internal';
352	    }
353	
354	    let body = null;
355	    if (this.is('{')) body = this.parseBlock();
356	    else this.accept(';');
357	
358	    return {
359	      kind: 'function', functionKind: kind, name, contractName,
360	      params, returnParams, visibility, stateMutability, isVirtual,
361	      modifiers, body, loc: this.loc(startTok),
362	    };
363	  }
364	
365	  parseModifierInvocation() {
366	    let name = this.expectIdent();
367	    while (this.accept('.')) name = this.expectIdent();
368	    if (this.is('(')) this.skipBalancedParens();
369	    return name;
370	  }
371	
372	  parseParameterList() {
373	    this.eat('(');
374	    const params = [];
375	    while (!this.is(')') && !this.atEnd()) {
376	      const typeNode = this.parseTypeName();
377	      const keywords = [];
378	      while (this.cur().type === 'keyword' &&
379	             (LOCATION_KEYWORDS.has(this.cur().value) || this.cur().value === 'indexed' ||
380	              this.cur().value === 'payable')) {
381	        keywords.push(this.cur().value);
382	        this.pos++;
383	      }
384	      let name = null;
385	      if (this.cur().type === 'ident') { name = this.cur().value; this.pos++; }
386	      // rare: location keyword after name
387	      while (this.cur().type === 'keyword' && LOCATION_KEYWORDS.has(this.cur().value)) this.pos++;
388	      params.push({
389	        name,
390	        typeNode,
391	        dataLocation: keywords.includes('calldata') ? 'calldata'
392	          : keywords.includes('memory') ? 'memory'
393	          : keywords.includes('storage') ? 'storage' : null,
394	      });
395	      if (!this.accept(',')) break;
396	    }
397	    this.eat(')');
398	    return params;
399	  }
400	
401	  // ---- Type names -------------------------------------------------------
402	
403	  parseTypeName() {
404	    const startTok = this.cur();
405	    if (this.isKw('mapping')) {
406	      this.pos++;
407	      this.eat('(');
408	      const keyType = this.parseTypeName();
409	      // '=>' is lexed as a single token; tolerate '=' '>' as well.
410	      if (this.is('=>')) this.pos++;
411	      else { this.eat('='); this.eat('>'); }
412	      const valueType = this.parseTypeName();
413	      this.eat(')');
414	      return { kind: 'typeMapping', keyType, valueType, loc: this.loc(startTok) };
415	    }
416	    if (this.isKw('function')) {
417	      // function type, e.g. function(uint) external view returns (uint)
418	      this.pos++;
419	      this.parseParameterList();
420	      if (this.acceptKw('returns')) this.parseParameterList();
421	      while (this.cur().type === 'keyword' &&
422	             ['internal', 'external', 'pure', 'view', 'payable'].includes(this.cur().value)) {
423	        this.pos++;
424	      }
425	      return { kind: 'typeFunction', loc: this.loc(startTok) };
426	    }
427	    const path = [this.typePathIdent()];
428	    while (this.accept('.')) path.push(this.expectIdent());
429	    this.acceptKw('payable');
430	    let node = { kind: 'typeElementary', path, loc: this.loc(startTok) };
431	    while (this.is('[')) {
432	      this.pos++;
433	      let length = null;
434	      if (!this.is(']')) length = this.parseExpression();
435	      this.eat(']');
436	      node = { kind: 'typeArray', base: node, length, loc: spanOf(startTok, this.tokens[this.pos - 1]) };
437	    }
438	    return node;
439	  }
440	
441	  typePathIdent() {
442	    const t = this.cur();
443	    if (t.type === 'ident' || (t.type === 'keyword' && TYPE_KEYWORDS.has(t.value))) {
444	      this.pos++;
445	      return t.value;
446	    }
447	    throw new ParseError(`Expected type name but found '${t.value || t.type}'`, t);
448	  }
449	
450	  // ---- Statements -------------------------------------------------------
451	
452	  parseBlock() {
453	    const startTok = this.cur();
454	    this.eat('{');
455	    const statements = [];
456	    while (!this.is('}') && !this.atEnd()) {
457	      const s = this.parseStatement();
458	      if (s) statements.push(s);
459	    }
460	    this.eat('}');
461	    return { kind: 'block', statements, loc: this.loc(startTok) };
462	  }
463	
464	  parseStatement() {
465	    const t = this.cur();
466	    if (IS(t, '{')) return this.parseBlock();
467	    if (IS(t, ';')) { this.pos++; return null; }
468	    if (KW(t, 'if')) return this.parseIf();
469	    if (KW(t, 'while')) return this.parseWhile();
470	    if (KW(t, 'do')) return this.parseDoWhile();
471	    if (KW(t, 'for')) return this.parseFor();
472	    if (KW(t, 'return')) return this.parseReturn();
473	    if (KW(t, 'break') || KW(t, 'continue')) {
474	      const startTok = t; this.pos++; this.eat(';');
475	      return { kind: t.value, loc: this.loc(startTok) };
476	    }
477	    if (KW(t, 'throw')) {
478	      const startTok = t; this.pos++; this.accept(';');
479	      return { kind: 'throw', loc: this.loc(startTok) };
480	    }
481	    if (KW(t, 'unchecked')) {
482	      const startTok = t; this.pos++;
483	      const body = this.parseBlock();
484	      return { kind: 'unchecked', body, loc: this.loc(startTok) };
485	    }
486	    if (KW(t, 'assembly')) return this.parseAssembly();
487	    if (KW(t, 'try')) return this.parseTry();
488	    if (KW(t, 'emit')) {
489	      const startTok = t; this.pos++;
490	      const expr = this.parseExpression();
491	      this.eat(';');
492	      return { kind: 'emit', expr, loc: this.loc(startTok) };
493	    }
494	    if (KW(t, 'revert')) {
495	      // revert; | revert("msg") | revert CustomError(args)
496	      const startTok = t; this.pos++;
497	      let args = [];
498	      if (this.cur().type === 'ident' && this.peek(1) && this.nextIs('(', 1)) {
499	        this.pos++; // error name
500	      }
501	      if (this.is('(')) args = this.parseCallArguments();
502	      this.eat(';');
503	      const expr = {
504	        kind: 'call',
505	        callee: { kind: 'ident', name: 'revert', loc: this.loc(startTok) },
506	        args, options: null, loc: this.loc(startTok),
507	      };
508	      return { kind: 'expression', expr, loc: this.loc(startTok) };
509	    }
510	    if (KW(t, 'delete')) {
511	      const startTok = t; this.pos++;
512	      const expr = this.parseExpression();
513	      this.eat(';');
514	      return { kind: 'expression', expr: { kind: 'unary', op: 'delete', prefix: true, operand: expr, loc: this.loc(startTok) }, loc: this.loc(startTok) };
515	    }
516	    if (t.type === 'ident' && t.value === '_' && this.peek(1) && IS(this.peek(1), ';')) {
517	      this.pos += 2;
518	      return { kind: 'placeholder', loc: this.loc(t) };
519	    }
520	
521	    const varDecl = this.tryParseVariableDeclaration();
522	    if (varDecl) return varDecl;
523	
524	    const startTok = t;
525	    const expr = this.parseExpression();
526	    this.eat(';');
527	    return { kind: 'expression', expr, loc: this.loc(startTok) };
528	  }
529	
530	  parseIf() {
531	    const startTok = this.cur();
532	    this.pos++;
533	    this.eat('(');
534	    const test = this.parseExpression();
535	    this.eat(')');
536	    const consequent = this.parseStatement();
537	    let alternate = null;
538	    if (this.acceptKw('else')) alternate = this.parseStatement();
539	    return { kind: 'if', test, consequent, alternate, loc: this.loc(startTok) };
540	  }
541	  parseWhile() {
542	    const startTok = this.cur();
543	    this.pos++;
544	    this.eat('(');
545	    const test = this.parseExpression();
546	    this.eat(')');
547	    const body = this.parseStatement();
548	    return { kind: 'while', test, body, loc: this.loc(startTok) };
549	  }
550	  parseDoWhile() {
551	    const startTok = this.cur();
552	    this.pos++;
553	    const body = this.parseStatement();
554	    this.eatKw('while');
555	    this.eat('(');
556	    const test = this.parseExpression();
557	    this.eat(')');
558	    this.eat(';');
559	    return { kind: 'doWhile', body, test, loc: this.loc(startTok) };
560	  }
561	  parseFor() {
562	    const startTok = this.cur();
563	    this.pos++;
564	    this.eat('(');
565	    let init = null;
566	    if (!this.is(';')) {
567	      init = this.tryParseVariableDeclaration({ noSemicolon: true });
568	      if (!init) {
569	        const expr = this.parseExpression();
570	        init = { kind: 'expression', expr, loc: expr.loc };
571	      }
572	    }
573	    this.eat(';');
574	    let test = null;
575	    if (!this.is(';')) test = this.parseExpression();
576	    this.eat(';');
577	    let update = null;
578	    if (!this.is(')')) update = this.parseExpression();
579	    this.eat(')');
580	    const body = this.parseStatement();
581	    return { kind: 'for', init, test, update, body, loc: this.loc(startTok) };
582	  }
583	  parseReturn() {
584	    const startTok = this.cur();
585	    this.pos++;
586	    let expr = null;
587	    if (!this.is(';')) expr = this.parseExpression();
588	    this.eat(';');
589	    return { kind: 'return', expr, loc: this.loc(startTok) };
590	  }
591	  parseAssembly() {
592	    const startTok = this.cur();
593	    this.pos++;
594	    // optional quoted dialect / quoted name list
595	    if (this.cur().type === 'string') this.pos++;
596	    // optional identifier (assembly name)
597	    if (this.cur().type === 'ident') this.pos++;
598	    if (this.cur().type === 'string') this.pos++;
599	    this.eat('{');
600	    let depth = 1;
601	    while (!this.atEnd() && depth > 0) {
602	      const t = this.cur();
603	      if (IS(t, '{')) depth++;
604	      else if (IS(t, '}')) depth--;
605	      if (depth === 0) { this.pos++; break; }
606	      this.pos++;
607	    }
608	    return { kind: 'assembly', loc: this.loc(startTok) };
609	  }
610	  parseTry() {
611	    const startTok = this.cur();
612	    this.pos++;
613	    const externalCall = this.parseExpression();
614	    let returns = null;
615	    if (this.acceptKw('returns')) returns = this.parseParameterList();
616	    const body = this.parseBlock();
617	    const clauses = [];
618	    while (this.isKw('catch')) {
619	      this.pos++;
620	      if (this.cur().type === 'ident') this.pos++; // Error / Panic keyword-ish name
621	      if (this.is('(')) this.parseParameterList();
622	      clauses.push(this.parseBlock());
623	    }
624	    return { kind: 'try', externalCall, returns, body, clauses, loc: this.loc(startTok) };
625	  }
626	
627	  tryParseVariableDeclaration(opts = {}) {
628	    const noSemicolon = !!opts.noSemicolon;
629	    const startTok = this.cur();
630	
631	    // Tuple declaration: (Type a, Type b) = ...  /  (Type a, ...)
632	    if (this.is('(')) {
633	      const save = this.pos;
634	      this.pos++;
635	      const components = [];
636	      let ok = true;
637	      while (!this.is(')') && !this.atEnd()) {
638	        if (this.is(',')) { components.push(null); this.pos++; continue; }
639	        const cs = this.pos;
640	        let typeNode;
641	        try { typeNode = this.parseTypeName(); } catch (e) { ok = false; break; }
642	        if (this.pos === cs) { ok = false; break; }
643	        const kws = [];
644	        while (this.cur().type === 'keyword' &&
645	               (LOCATION_KEYWORDS.has(this.cur().value) || this.cur().value === 'constant')) {
646	          kws.push(this.cur().value); this.pos++;
647	        }
648	        if (this.cur().type !== 'ident') { ok = false; break; }
649	        const nameTok = this.cur(); this.pos++;
650	        components.push({
651	          name: nameTok.value, typeNode,
652	          dataLocation: kws.includes('storage') ? 'storage'
653	            : kws.includes('memory') ? 'memory'
654	            : kws.includes('calldata') ? 'calldata' : null,
655	        });
656	        if (this.is(',')) continue;
657	        break;
658	      }
659	      if (ok && this.is(')') && components.some((c) => c !== null)) {
660	        this.pos++;
661	        while (this.cur().type === 'keyword' && LOCATION_KEYWORDS.has(this.cur().value)) this.pos++;
662	        let initializer = null;
663	        if (this.accept('=')) initializer = this.parseExpression();
664	        if (!noSemicolon) this.eat(';');
665	        return {
666	          kind: 'varDecl', components, initializer, loc: this.loc(startTok),
667	          names: components.filter(Boolean).map((c) => c.name),
668	        };
669	      }
670	      this.pos = save;
671	    }
672	
673	    // Simple declaration: TypeName name [loc] (= expr)?
674	    const save = this.pos;
675	    let typeNode;
676	    try {
677	      typeNode = this.parseTypeName();
678	    } catch (e) {
679	      this.pos = save;
680	      return null;
681	    }
682	    if (this.pos === save) return null;
683	    while (this.cur().type === 'keyword' && LOCATION_KEYWORDS.has(this.cur().value)) this.pos++;
684	    if (this.cur().type !== 'ident') { this.pos = save; return null; }
685	    const nameTok = this.cur();
686	    const cont = this.peek(1);
687	    const isCont = cont && (IS(cont, ';') || IS(cont, '=') || IS(cont, ',') ||
688	      (cont.type === 'keyword' && (LOCATION_KEYWORDS.has(cont.value) || cont.value === 'constant')));
689	    if (!isCont) { this.pos = save; return null; }
690	    this.pos++;
691	    const kws = [];
692	    while (this.cur().type === 'keyword' &&
693	           (LOCATION_KEYWORDS.has(this.cur().value) || this.cur().value === 'constant')) {
694	      kws.push(this.cur().value); this.pos++;
695	    }
696	    let initializer = null;
697	    if (this.accept('=')) initializer = this.parseExpression();
698	    if (!noSemicolon) this.eat(';');
699	    const comp = {
700	      name: nameTok.value, typeNode,
701	      dataLocation: kws.includes('storage') ? 'storage'
702	        : kws.includes('memory') ? 'memory'
703	        : kws.includes('calldata') ? 'calldata' : null,
704	    };
705	    return {
706	      kind: 'varDecl', components: [comp], initializer, loc: this.loc(startTok),
707	      names: [nameTok.value],
708	    };
709	  }
710	
711	  // ---- Expressions ------------------------------------------------------
712	
713	  parseExpression() {
714	    return this.parseAssignment();
715	  }
716	
717	  parseAssignment() {
718	    const left = this.parseTernary();
719	    const t = this.cur();
720	    if (t.type === 'punct' && ['=', '+=', '-=', '*=', '/=', '%=', '|=', '&=', '^=', '<<=', '>>='].includes(t.value)) {
721	      const op = t.value;
722	      this.pos++;
723	      const value = this.parseAssignment();
724	      return {
725	        kind: 'assign', op, target: left, value,
726	        loc: {
727	          startOffset: left.loc.startOffset, startLine: left.loc.startLine,
728	          startColumn: left.loc.startColumn,
729	          endOffset: value.loc.endOffset, endLine: value.loc.endLine,
730	          endColumn: value.loc.endColumn,
731	        },
732	      };
733	    }
734	    return left;
735	  }
736	
737	  parseTernary() {
738	    const test = this.parseBinary(0);
739	    if (this.accept('?')) {
740	      const cons = this.parseAssignment();
741	      this.eat(':');
742	      const alt = this.parseTernary();
743	      return { kind: 'conditional', test, cons, alt, loc: { ...test.loc, endOffset: alt.loc.endOffset, endLine: alt.loc.endLine, endColumn: alt.loc.endColumn } };
744	    }
745	    return test;
746	  }
747	
748	  // precedence: higher binds tighter
749	  static BINARY_PRECEDENCE = {
750	    '||': 1, '&&': 2,
751	    '|': 3, '^': 4, '&': 5,
752	    '==': 6, '!=': 6,
753	    '<': 7, '>': 7, '<=': 7, '>=': 7,
754	    '<<': 8, '>>': 8,
755	    '+': 9, '-': 9,
756	    '*': 10, '/': 10, '%': 10,
757	    '**': 11,
758	  };
759	
760	  parseBinary(minPrec) {
761	    let left = this.parseUnary();
762	    for (;;) {
763	      const t = this.cur();
764	      const prec = t.type === 'punct' ? Parser.BINARY_PRECEDENCE[t.value] : undefined;
765	      if (prec === undefined || prec < minPrec) break;
766	      this.pos++;
767	      const right = this.parseBinary(prec === 11 ? prec : prec + 1);
768	      left = {
769	        kind: 'binary', op: t.value, left, right,
770	        loc: {
771	          startOffset: left.loc.startOffset, startLine: left.loc.startLine,
772	          startColumn: left.loc.startColumn,
773	          endOffset: right.loc.endOffset, endLine: right.loc.endLine,
774	          endColumn: right.loc.endColumn,
775	        },
776	      };
777	    }
778	    return left;
779	  }
780	
781	  parseUnary() {
782	    const t = this.cur();
783	    if (t.type === 'punct' && ['!', '~', '-', '+', '++', '--'].includes(t.value)) {
784	      this.pos++;
785	      const operand = this.parseUnary();
786	      return { kind: 'unary', op: t.value, prefix: true, operand, loc: this.loc(t) };
787	    }
788	    if (KW(t, 'after') || KW(t, 'delete')) {
789	      this.pos++;
790	      const operand = this.parseUnary();
791	      return { kind: 'unary', op: KW(t, 'after') ? 'after' : 'delete', prefix: true, operand, loc: this.loc(t) };
792	    }
793	    return this.parsePostfix();
794	  }
795	
796	  parsePostfix() {
797	    let node = this.parsePrimary();
798	    for (;;) {
799	      if (this.accept('.')) {
800	        const propTok = this.cur();
801	        const property = this.expectIdent();
802	        node = {
803	          kind: 'member', object: node, property,
804	          propertyLoc: this.loc(propTok), loc: this.loc(this.firstTok(node)),
805	        };
806	        continue;
807	      }
808	      if (this.is('[')) {
809	        const startTok = this.firstTok(node);
810	        this.pos++;
811	        let index = null;
812	        if (!this.is(']')) index = this.parseExpression();
813	        this.eat(']');
814	        node = { kind: 'index', object: node, index, loc: this.loc(startTok) };
815	        continue;
816	      }
817	      if (this.is('(')) {
818	        const startTok = this.firstTok(node);
819	        const args = this.parseCallArguments();
820	        node = { kind: 'call', callee: node, args, options: null, loc: this.loc(startTok) };
821	        continue;
822	      }
823	      // call options: callee {value: x, gas: y} ( args )
824	      if (this.is('{') && this.callOptionsAhead()) {
825	        const startTok = this.firstTok(node);
826	        const options = this.parseCallOptions();
827	        const args = this.parseCallArguments();
828	        node = { kind: 'call', callee: node, args, options, loc: this.loc(startTok) };
829	        continue;
830	      }
831	      if (this.isPunct('++') || this.isPunct('--')) {
832	        const op = this.cur().value;
833	        const startTok = this.firstTok(node);
834	        this.pos++;
835	        node = { kind: 'unary', op, prefix: false, operand: node, loc: this.loc(startTok) };
836	        continue;
837	      }
838	      break;
839	    }
840	    return node;
841	  }
842	
843	  isPunct(v) { return this.is(v); }
844	
845	  firstTok(node) {
846	    for (const tk of this.tokens) if (tk.start === node.loc.startOffset) return tk;
847	    return this.cur();
848	  }
849	
850	  callOptionsAhead() {
851	    // { ... } must be immediately followed by '(' to count as options.
852	    let i = this.pos;
853	    if (!IS(this.tokens[i], '{')) return false;
854	    let depth = 0;
855	    for (; i < this.tokens.length; i++) {
856	      const t = this.tokens[i];
857	      if (IS(t, '{') || IS(t, '(') || IS(t, '[')) depth++;
858	      else if (IS(t, '}') || IS(t, ')') || IS(t, ']')) {
859	        depth--;
860	        if (depth === 0) { i++; break; }
861	      } else if (IS(t, ';') && depth === 0) return false;
862	    }
863	    return i < this.tokens.length && IS(this.tokens[i], '(');
864	  }
865	
866	  parseCallOptions() {
867	    this.eat('{');
868	    const options = [];
869	    while (!this.is('}') && !this.atEnd()) {
870	      const name = this.expectIdent();
871	      this.eat(':');
872	      const value = this.parseExpression();
873	      options.push({ name, value });
874	      if (!this.accept(',')) break;
875	    }
876	    this.eat('}');
877	    return options;
878	  }
879	
880	  parseCallArguments() {
881	    this.eat('(');
882	    const args = [];
883	    while (!this.is(')') && !this.atEnd()) {
884	      if (this.is('{')) {
885	        // struct literal argument: { name: expr, ... }
886	        args.push(this.parseStructLiteral());
887	      } else {
888	        // named call arguments: {name: expr} are normally brace-led;
889	        // here handle plain expressions
890	        args.push(this.parseExpression());
891	      }
892	      if (!this.accept(',')) break;
893	    }
894	    this.eat(')');
895	    return args;
896	  }
897	
898	  parseStructLiteral() {
899	    const startTok = this.cur();
900	    this.eat('{');
901	    const fields = [];
902	    while (!this.is('}') && !this.atEnd()) {
903	      const name = this.expectIdent();
904	      this.eat(':');
905	      const value = this.parseExpression();
906	      fields.push({ name, value });
907	      if (!this.accept(',')) break;
908	    }
909	    this.eat('}');
910	    return { kind: 'structLiteral', fields, loc: this.loc(startTok) };
911	  }
912	
913	  parsePrimary() {
914	    const t = this.cur();
915	    if (t.type === 'number' || t.type === 'string') {
916	      this.pos++;
917	      return { kind: 'literal', literalType: t.type, value: t.value, loc: this.loc(t) };
918	    }
919	    if (KW(t, 'new')) {
920	      this.pos++;
921	      const typeNode = this.parseTypeName();
922	      return { kind: 'newExpr', typeNode, loc: this.loc(t) };
923	    }
924	    if (t.type === 'ident' || t.type === 'keyword') {
925	      // keywords usable as values (true/false are idents; address casts etc.)
926	      this.pos++;
927	      return { kind: 'ident', name: t.value, loc: this.loc(t) };
928	    }
929	    if (IS(t, '(')) {
930	      this.pos++;
931	      const items = [];
932	      while (!this.is(')') && !this.atEnd()) {
933	        if (this.is(',')) { items.push(null); this.pos++; continue; }
934	        items.push(this.parseAssignment());
935	        if (this.is(')')) break;
936	        if (!this.accept(',')) break;
937	      }
938	      this.eat(')');
