function testPathSensitiveBranches() {
  const sb = makeSandbox();
  sb.write('paths.sol', `
pragma solidity ^0.8.0;
interface IT { function f() external; }
contract C {
    uint256 x;
    function mutex(address a, bool b) public {
        if (b) { x = 1; } else { a.call(""); }
    }
    function sameBranch(address a, bool b) public {
        if (b) { a.call(""); x = 2; }
    }
    function loopCase(address a) public {
        for (uint256 i = 0; i < 2; i++) {
            if (i == 0) { a.call(""); }
            if (i == 1) { x = 3; }
        }
    }
    function tryCatch() public {
        try IT(address(0)).f() {
            x = 4;
        } catch {
            x = 5;
        }
    }
    function earlyReturn(address a, bool b) public {
        a.call("");
        if (b) { return; }
        x = 6;
    }
    function afterReturn(address a, bool b) public {
        if (b) { return; }
        else { a.call(""); }
        x = 7;
    }
}
`);
  const r = run(path.join(sb.dir, 'paths.sol'));
  assert(r.code === 0, `paths: exit 0 (got ${r.code} ${r.stdout})`);
  const lines = rules(r.json.findings, 'STATE_UPDATE_AFTER_CALL')
    .map((h) => h.location.startLine).sort((a, b) => a - b);
  // Blank line 1: sameBranch x=2 (10), loop x=3 (16), try x=4 (21),
  // catch x=5 (23, both clauses follow the tried call), earlyReturn x=6 (30).
  // mutex x=1 (6) and afterReturn x=7 (35) excluded (mutex branches /
  // interaction on the return-terminated path).
  assert(lines.join(',') === '10,16,21,23,30',
    `paths: path-sensitive lines 10,16,21,23,30 got ${lines}`);
  sb.remove();
}

